# tests/test_entropy_estimators.R
#
# Reference validation and invariant checks for the D2 diversity estimators in
# `R/shannon_entropy.R` (Stage A2 of docs/ESTIMATOR_PIVOT_PLAN.md).
#
# Run from the repository root:
#     Rscript tests/test_entropy_estimators.R
#
# WHY THE EXPECTED VALUES ARE HARDCODED
#
# The 22 fixtures below were generated by evaluating `entropy_estimates()`
# against the CRAN `entropy` package version 1.3.2 — `entropy.empirical()`,
# `entropy.ChaoShen()` and `entropy.MillerMadow()`, all with `unit = "log2"` —
# and asserting agreement to within 1e-10. The largest observed absolute
# disagreement across all 22 cases and all three estimators was 1.26e-12, on
# `all_singletons_long`; every other case agreed to within 2.1e-14.
#
# That residual is the reference implementation's, not ours. `entropy::
# entropy.ChaoShen()` forms the Horvitz-Thompson inclusion probability as the
# naive `1 - (1 - pa)^n`, which loses significant digits when `pa` is small and
# `n` is large; `R/shannon_entropy.R` uses `-expm1(n * log1p(-pa))`, which does
# not. The two agree to 1e-12 at fixture scale and diverge in the reference's
# disfavour at Visium scale (pa ~ 1e-4, n ~ 1e4), which is the regime this
# project actually runs in.
#
# The `entropy` package was then dropped rather than pinned. It exists in this
# repository only as these numbers. Installing a CRAN package into the pinned
# conda environment to check ~40 lines of arithmetic once is the same trade D3
# already made when it rejected `ppcor` for the partial correlations, and the
# validation survives the removal because the expected values do. To re-verify
# after changing the kernel, install `entropy` into a throwaway library and
# regenerate; do not add it to `environment.yml`.
#
# No test framework either, for the same reason: this file needs base R and
# Matrix, both of which the pipeline already requires.

source("R/shannon_entropy.R")

TOL <- 1e-10

n_pass <- 0L
n_fail <- 0L

check <- function(label, ok, detail = "") {
  if (isTRUE(ok)) {
    n_pass <<- n_pass + 1L
  } else {
    n_fail <<- n_fail + 1L
    cat(sprintf("FAIL  %s%s\n", label, if (nchar(detail)) paste0("  [", detail, "]") else ""))
  }
}

check_close <- function(label, actual, expected, tol = TOL) {
  d <- max(abs(actual - expected))
  check(label, is.finite(d) && d <= tol, sprintf("max abs diff %.3e > %.1e", d, tol))
}

