cat("--- 1. reference fixtures (CRAN entropy 1.3.2, tol 1e-10) ---\n")
for (nm in names(fixtures)) {
  f <- fixtures[[nm]]
  got <- entropy_estimates(f$y)
  check_close(sprintf("fixture %s", nm), got[names(f$expected)], f$expected)
}

# ---------------------------------------------------------------------------
# 2. Degenerate spots
# ---------------------------------------------------------------------------

cat("--- 2. degenerate spots ---\n")

# A spot with no counts at all. The CRAN reference returns NaN here (0/0 in the
# empirical frequencies); this project's convention, inherited from
# plugin_entropy_matrix(), is that an empty spot has zero entropy. Asserted so
# that the divergence from the reference is deliberate and recorded rather than
# discovered later in a spatial plot.
check_close("empty spot returns 0 for every estimator", entropy_estimates(rep(0, 5)), rep(0, 4))

# f1 == N (every observed gene a singleton) drives Good-Turing coverage to zero
# and the estimator to total degeneracy. The f1 := N - 1 substitution must keep
# every estimate finite. This is rare at Visium depths but occurs in the shallow
# tail, where an unguarded NaN would propagate silently.
for (nm in c("all_singletons", "all_singletons_long", "two_singletons", "single_count_total_one")) {
  check(sprintf("f1 == N guard keeps %s finite", nm), all(is.finite(entropy_estimates(fixtures[[nm]]$y))))
}

# f1 == 0 and f2 == 0 makes the Chao-Wang-Jost bracket 0/0; the limit is a zero
# correction (C = 1), not NaN.
check("CWJ 0/0 bracket resolves to C = 1", all(is.finite(entropy_estimates(c(5, 3, 4, 7)))))

# ---------------------------------------------------------------------------
# 3. Ordering invariants
# ---------------------------------------------------------------------------

cat("--- 3. ordering invariants ---\n")

fx <- do.call(rbind, lapply(fixtures, function(f) as.data.frame(as.list(entropy_estimates(f$y)))))

# Both corrections are upward, so these two hold by construction and a violation
# is a bug rather than a finding.
check("plugin <= miller_madow on every fixture", all(fx$miller_madow >= fx$plugin - TOL))
check("plugin <= chao_shen on every fixture", all(fx$chao_shen >= fx$plugin - TOL))
check("plugin <= chao_shen_cwj on every fixture", all(fx$chao_shen_cwj >= fx$plugin - TOL))

# miller_madow <= chao_shen is NOT a theorem, and this assertion pins that.
# Five of the 22 fixtures violate it — uniform_small, uniform_large,
# no_singletons, poisson_deep and half_singletons — which is every fixture with
# f1 = 0 plus one with a light singleton tail. Miller-Madow's correction depends
# only on K/N and so keeps growing with the observed support, while Chao-Shen's
# is driven by f1/N and vanishes when there are no singletons: with f1 = 0 the
# coverage estimate is 1 and Chao-Shen reduces to the plug-in value inflated
# only by the inclusion-probability denominator. An implementation that asserted
# the full plugin <= MM <= CS chain would report a bug on correct output.
n_mm_gt_cs <- sum(fx$chao_shen < fx$miller_madow - TOL)
check("miller_madow <= chao_shen is not universal (>= 1 counterexample)", n_mm_gt_cs >= 1,
      sprintf("counterexamples: %d", n_mm_gt_cs))
check("counterexamples are exactly the f1 == 0 / light-singleton cases", n_mm_gt_cs == 5,
      sprintf("expected 5, got %d", n_mm_gt_cs))

# check_entropy_ordering() must enforce the two real invariants and merely
# report the third.
ord <- check_entropy_ordering(fx)
check("check_entropy_ordering flags 3 invariants + 1 observation", nrow(ord) == 4 && sum(ord$Invariant) == 3)
check("check_entropy_ordering passes clean data", all(ord$N_Violations[ord$Invariant] == 0))
broken <- fx
broken$chao_shen[1] <- broken$plugin[1] - 1
check("check_entropy_ordering errors on a violated invariant",
      inherits(try(check_entropy_ordering(broken), silent = TRUE), "try-error"))

# Chao-Shen routinely exceeds log2(K), the maximum entropy of the *observed*
# support, because it estimates the entropy of the full distribution including
# unseen genes. Correct behaviour, asserted so it is not later mistaken for one.
K_fx <- vapply(fixtures, function(f) sum(f$y > 0), numeric(1))
check("chao_shen may exceed log2(K) (unseen-support estimation)", any(fx$chao_shen > log2(K_fx) + TOL))

# ---------------------------------------------------------------------------
# 4. Kernel behaviour on matrices
# ---------------------------------------------------------------------------

cat("--- 4. sparse kernel ---\n")

set.seed(23)
G <- 400L; S <- 60L
dense <- matrix(rpois(G * S, 0.4), nrow = G)
rownames(dense) <- paste0("G", seq_len(G))
colnames(dense) <- paste0("S", seq_len(S))
sp <- as(as(as(dense, "dMatrix"), "generalMatrix"), "CsparseMatrix")

est <- entropy_estimator_matrix(sp, return_stats = TRUE)

# The plug-in column must be bit-identical to plugin_entropy_matrix(), not
# merely close: `entropy_plugin` and the pipeline's `entropy_raw_plugin` column
# (D2) have to be the same number for the Stage A bake-off to compare the new
# estimators against the recorded baseline rather than against a re-derivation.
check("plugin identical to plugin_entropy_matrix (bitwise)",
      identical(unname(plugin_entropy_matrix(sp)), est$plugin))

# Per-column results must equal the single-vector path.
per_col <- t(vapply(seq_len(S), function(j) entropy_estimates(dense[, j]), numeric(4)))
check_close("matrix kernel agrees with per-column vector calls",
            as.matrix(est[, ENTROPY_ESTIMATORS]), per_col[, ENTROPY_ESTIMATORS])

# Blocking is an implementation detail and must not move any number.
old_opt <- getOption("entropy.block.nnz")
options(entropy.block.nnz = 50)
est_small <- entropy_estimator_matrix(sp)
options(entropy.block.nnz = 5e7)
est_big <- entropy_estimator_matrix(sp)
options(entropy.block.nnz = old_opt)
check("block size does not change results (nnz budget 50)",
      identical(est_small, est_big))
check_close("blocked result matches default budget",
            as.matrix(est_small), as.matrix(est[, ENTROPY_ESTIMATORS]))

# ---------------------------------------------------------------------------
# 5. Explicitly-stored zeros (the drop0 guard)
# ---------------------------------------------------------------------------

cat("--- 5. structural zeros ---\n")

# Seurat's subset() and the gene-universe filter leave structurally-stored
# explicit zeros behind. diff(@p) counts stored entries, not non-zero entries,
# so K, f1 and f2 are silently wrong without drop0() — and wrong in a way that
# biases the shallow spots the correction exists to rescue. This fixture makes
# the guard load-bearing: without it, K would be inflated by the injected zeros
# and Miller-Madow's (K-1)/(2N ln2) term would be inflated with it.
padded <- sp
zero_idx <- which(padded@x > 0)[seq(1, sum(padded@x > 0), by = 7)]
padded@x[zero_idx] <- 0
check("test fixture actually carries explicit zeros",
      any(padded@x == 0) && !identical(diff(padded@p), diff(Matrix::drop0(padded)@p)))

est_padded <- entropy_estimator_matrix(padded, return_stats = TRUE)
true_K <- as.numeric(Matrix::colSums(padded != 0))
check("K counts non-zero entries, not stored entries", identical(est_padded$K, true_K))
true_f1 <- as.numeric(Matrix::colSums(padded == 1))
true_f2 <- as.numeric(Matrix::colSums(padded == 2))
check("f1 counts singletons, unaffected by explicit zeros", identical(est_padded$f1, true_f1))
check("f2 counts doubletons, unaffected by explicit zeros", identical(est_padded$f2, true_f2))
check_close("estimates on a zero-padded matrix match the dropped one",
            as.matrix(est_padded[, ENTROPY_ESTIMATORS]),
            as.matrix(entropy_estimator_matrix(Matrix::drop0(padded))))

# ---------------------------------------------------------------------------
# 6. The counts assertion
# ---------------------------------------------------------------------------

cat("--- 6. counts assertion ---\n")

# f1 and f2 are counts of singleton and doubleton reads. On a normalized layer
# they are meaningless, and pointing an estimator at one is the category error
# that produced the entropy_spanorm_plugin defect recorded in D2. The kernel
# must refuse rather than return a plausible number.
normalized <- sp
normalized@x <- log2(normalized@x + 1)
check("non-integer matrix is rejected",
      inherits(try(entropy_estimator_matrix(normalized), silent = TRUE), "try-error"))

negative <- sp
negative@x[1] <- -1
check("negative values are rejected",
      inherits(try(entropy_estimator_matrix(negative), silent = TRUE), "try-error"))

check("check_counts = FALSE bypasses the assertion",
      !inherits(try(entropy_estimator_matrix(normalized, estimators = "plugin",
                                             check_counts = FALSE), silent = TRUE), "try-error"))

# ---------------------------------------------------------------------------

cat(sprintf("\n%d passed, %d failed\n", n_pass, n_fail))
if (n_fail > 0) quit(status = 1)
